export interface LogoImage {
  src: string;
  /** Intrinsic size of the white file */
  width: number;
  height: number;
  /** Share of the box covered by the logo (0–1), from the generator */
  density: number;
  /** Optical correction (1 = none) */
  tune: number;
}

/** White version of a supplied logo file, or undefined if it has not been generated. */
export function whiteLogo(file: string | undefined): LogoImage | undefined {
  const size = file ? (logoSizes[file] ?? givebackLogoSizes[file] ?? tribeVectorLogoSizes[file]) : undefined;
  if (!file || !size) return undefined;
  const [width, height, density] = size;
  return {
    src: `/brand/logos-white/${file}`,
    width,
    height,
    density,
    tune: LOGO_TUNE[file] ?? 1,
  };
}

/** Typical ink density of the set: logos denser than this are drawn smaller, lighter ones larger. */
const REF_DENSITY = 0.28;

/**
 * Display size giving every logo the same visual weight: wide wordmarks and square marks cover about the same
 * area, corrected for ink density (a solid block reads heavier than thin lettering in the same box) and for the
 * per-logo optical tune; kept within the frame (maxW × maxH, which the tune may stretch for compact marks) and
 * never enlarged past maxScale × the file's own size (small source files would turn blurry).
 */
export function logoBox(logo: LogoImage, area: number, maxW: number, maxH: number, maxScale = 2.2) {
  const ratio = logo.width / logo.height;
  const density = Math.min(0.9, Math.max(0.1, logo.density));
  const target = area * Math.pow(REF_DENSITY / density, 0.55) * logo.tune * logo.tune;
  const limitH = maxH * Math.max(1, logo.tune);
  let w = Math.sqrt(target * ratio);
  let h = w / ratio;
  if (h > limitH) {
    h = limitH;
    w = h * ratio;
  }
  if (w > maxW) {
    w = maxW;
    h = w / ratio;
  }
  if (w > logo.width * maxScale) {
    w = logo.width * maxScale;
    h = w / ratio;
  }
  return { width: Math.round(w), height: Math.round(h) };
}

/** Every innovation advisory client, once, in alphabetical order. */
export const clientLogos: (LogoImage & { name: string })[] = (() => {
  const seen = new Set<string>();
  const out: (LogoImage & { name: string })[] = [];
  for (const p of advisory) {
    const file = advisoryLogoFiles[p.slug];
    const logo = whiteLogo(file);
    if (!logo || seen.has(file)) continue;
    seen.add(file);
    out.push({ ...logo, name: p.client });
  }
  return out.sort((a, b) => a.name.localeCompare(b.name, 'it', { sensitivity: 'base' }));
})();

/**
 * Giveback initiative (content/data/giveback.ts) → logo file. Wordmarks drawn in assets-src/logos/giveback until the
 * official files are supplied (scripts/generate-giveback-logos.cjs).
 */
export const givebackLogoFiles: Record<string, string> = {
  startuparty: 'startuparty.webp',
  'junior-jedi': 'juniorjedi.webp',
  'italian-rainforest': 'italianrainforest.webp',
};

/**
 * Scrolling banners (2026-10-27): the innovation advisory clients with the Giveback initiatives and, since 2026-11-10,
 * Buy Buy Shop and Trade to World spread evenly among them.
 */
export const bannerLogos: (LogoImage & { name: string })[] = (() => {
  const names: Record<string, string> = {
    startuparty: 'StartuParty',
    'junior-jedi': 'Junior Jedi',
    'italian-rainforest': 'Italian Rainforest',
    'buy-buy-shop': 'Buy Buy Shop',
    'trade-to-world': 'Trade to World',
  };
  const extra: [string, string][] = [
    ...Object.entries(givebackLogoFiles),
    ['buy-buy-shop', tribeLogoFiles['buy-buy-shop']],
    ['trade-to-world', tribeLogoFiles['trade-to-world']],
  ];
  const giveback = extra.flatMap(([slug, file]) => {
    const logo = whiteLogo(file);
    return logo ? [{ ...logo, name: names[slug] }] : [];
  });
  const out = [...clientLogos];
  const step = Math.floor(out.length / (giveback.length + 1));
  giveback.forEach((l, i) => out.splice(step * (i + 1) + i, 0, l));
  return out;
})();
